package com.pp.shaderlod.optimization.astraearlyalpha;public final class AstraEarlyAlphaContract{private AstraEarlyAlphaContract(){}public record Sampler(int texture,int width,int height,int min,int mag,int base,int compare,int compareFunction,float bias,float minLod,float maxLod,float anisotropy){}public static boolean sampler(Sampler s,int owned,boolean comparison){return s!=null&&owned>0&&s.texture()==owned&&s.width()>0&&s.height()>0&&(s.min()==0x2600||s.min()==0x2601)&&s.min()==s.mag()&&s.base()==0&&s.bias()==0&&Float.isFinite(s.minLod())&&Float.isFinite(s.maxLod())&&s.minLod()<=0&&s.maxLod()>=0&&s.anisotropy()==1&&s.compare()==(comparison?0x884E:0)&&(!comparison||s.compareFunction()==0x0203);}public static boolean alpha(float f){return Float.isFinite(f)&&f>=0&&f<=1;}}
